import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry sdpa_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 Out_ptr
)
{
    .reg .u32 %r<120>;
    .reg .u64 %rd<60>;
    .reg .f32 %f<80>;
    .reg .b16 %h<20>;
    .reg .pred %p<40>;

    .shared .align 8 .b8 Qs[2048];
    .shared .align 4 .b8 Sc[1024];
    .shared .align 4 .b8 Ex[1024];
    .shared .align 4 .b8 Rd[1024];

    ld.param.u64 %rd1, [Q_ptr];
    ld.param.u64 %rd2, [K_ptr];
    ld.param.u64 %rd3, [V_ptr];
    ld.param.u64 %rd4, [Out_ptr];

    mov.u32 %r1, %ctaid.x;      // idx : 0..16383 (B*H*S)
    mov.u32 %r2, %tid.x;        // tid : 0..255

    // bounds check: idx < 16384
    setp.ge.u32 %p1, %r1, 16384;
    @%p1 bra DONE_ALL;

    shr.u32 %r3, %r1, 8;        // bh = idx >> 8  (b*32+h)
    shl.b32 %r5, %r3, 8;        // bhS = bh << 8
    shl.b32 %r6, %r1, 11;       // byteOffQ = idx * 2048 (row byte offset, Q/Out share layout)

    cvt.u64.u32 %rd5, %r6;
    add.s64 %rd6, %rd1, %rd5;   // Qaddr = Qptr + byteOffQ (row base, global)

    mov.u32 %r10, Qs;
    mov.u32 %r11, Sc;
    mov.u32 %r12, Ex;
    mov.u32 %r13, Rd;

    shl.b32 %r43, %r2, 2;       // toff = tid*4
    add.u32 %r46, %r11, %r43;   // ScAddr (shared) for this thread
    add.u32 %r47, %r12, %r43;   // ExAddr (shared) for this thread
    add.u32 %r48, %r13, %r43;   // RdAddr (shared) for this thread

    // ---------------- Load Q row into shared memory (unrolled x4) ----------------
    shl.b32 %r50, %r2, 1;        // tid*2

    add.u32 %r51, %r50, 0;
    cvt.u64.u32 %rd10, %r51;
    add.s64 %rd11, %rd6, %rd10;
    ld.global.b16 %h1, [%rd11];
    add.u32 %r52, %r10, %r51;
    st.shared.b16 [%r52], %h1;

    add.u32 %r53, %r50, 512;
    cvt.u64.u32 %rd12, %r53;
    add.s64 %rd13, %rd6, %rd12;
    ld.global.b16 %h2, [%rd13];
    add.u32 %r54, %r10, %r53;
    st.shared.b16 [%r54], %h2;

    add.u32 %r55, %r50, 1024;
    cvt.u64.u32 %rd14, %r55;
    add.s64 %rd15, %rd6, %rd14;
    ld.global.b16 %h3, [%rd15];
    add.u32 %r56, %r10, %r55;
    st.shared.b16 [%r56], %h3;

    add.u32 %r57, %r50, 1536;
    cvt.u64.u32 %rd16, %r57;
    add.s64 %rd17, %rd6, %rd16;
    ld.global.b16 %h4, [%rd17];
    add.u32 %r58, %r10, %r57;
    st.shared.b16 [%r58], %h4;

    bar.sync 0;

    // ---------------- Compute score for key j = tid ----------------
    add.u32 %r14, %r5, %r2;      // rowIndexK = bhS + tid
    shl.b32 %r15, %r14, 11;      // byteOffK
    cvt.u64.u32 %rd20, %r15;
    add.s64 %rd21, %rd2, %rd20;  // Kaddr row base

    mov.f32 %f1, 0f00000000;
    mov.u32 %r16, 0;

SCORE_LOOP:
    setp.ge.u32 %p2, %r16, 1024;
    @%p2 bra SCORE_DONE;
    shl.b32 %r17, %r16, 1;
    add.u32 %r18, %r10, %r17;
    ld.shared.v4.b16 {%h5, %h6, %h7, %h8}, [%r18];
    cvt.u64.u32 %rd22, %r17;
    add.s64 %rd23, %rd21, %rd22;
    ld.global.v4.b16 {%h12, %h13, %h14, %h15}, [%rd23];
    cvt.f32.f16 %f2, %h5;
    cvt.f32.f16 %f3, %h12;
    fma.rn.f32 %f1, %f2, %f3, %f1;
    cvt.f32.f16 %f4, %h6;
    cvt.f32.f16 %f5, %h13;
    fma.rn.f32 %f1, %f4, %f5, %f1;
    cvt.f32.f16 %f6, %h7;
    cvt.f32.f16 %f7, %h14;
    fma.rn.f32 %f1, %f6, %f7, %f1;
    cvt.f32.f16 %f8, %h8;
    cvt.f32.f16 %f9, %h15;
    fma.rn.f32 %f1, %f8, %f9, %f1;
    add.u32 %r16, %r16, 4;
    bra SCORE_LOOP;

SCORE_DONE:
    mul.f32 %f1, %f1, 0f3D000000;   // scale = 1/32

    st.shared.f32 [%r46], %f1;      // Sc[tid] = raw score
    bar.sync 0;

    ld.shared.f32 %f4, [%r46];
    st.shared.f32 [%r48], %f4;      // Rd[tid] = copy for max reduction
    bar.sync 0;

    // ---------------- MAX REDUCTION ----------------
    setp.lt.u32 %p10, %r2, 128;
    @%p10 ld.shared.f32 %f10, [%r48];
    @%p10 add.u32 %r60, %r48, 512;
    @%p10 ld.shared.f32 %f11, [%r60];
    @%p10 max.f32 %f12, %f10, %f11;
    @%p10 st.shared.f32 [%r48], %f12;
    bar.sync 0;

    setp.lt.u32 %p11, %r2, 64;
    @%p11 ld.shared.f32 %f13, [%r48];
    @%p11 add.u32 %r61, %r48, 256;
    @%p11 ld.shared.f32 %f14, [%r61];
    @%p11 max.f32 %f15, %f13, %f14;
    @%p11 st.shared.f32 [%r48], %f15;
    bar.sync 0;

    setp.lt.u32 %p12, %r2, 32;
    @%p12 ld.shared.f32 %f16, [%r48];
    @%p12 add.u32 %r62, %r48, 128;
    @%p12 ld.shared.f32 %f17, [%r62];
    @%p12 max.f32 %f18, %f16, %f17;
    @%p12 st.shared.f32 [%r48], %f18;
    bar.sync 0;

    setp.lt.u32 %p13, %r2, 16;
    @%p13 ld.shared.f32 %f19, [%r48];
    @%p13 add.u32 %r63, %r48, 64;
    @%p13 ld.shared.f32 %f20, [%r63];
    @%p13 max.f32 %f21, %f19, %f20;
    @%p13 st.shared.f32 [%r48], %f21;
    bar.sync 0;

    setp.lt.u32 %p14, %r2, 8;
    @%p14 ld.shared.f32 %f22, [%r48];
    @%p14 add.u32 %r64, %r48, 32;
    @%p14 ld.shared.f32 %f23, [%r64];
    @%p14 max.f32 %f24, %f22, %f23;
    @%p14 st.shared.f32 [%r48], %f24;
    bar.sync 0;

    setp.lt.u32 %p15, %r2, 4;
    @%p15 ld.shared.f32 %f25, [%r48];
    @%p15 add.u32 %r65, %r48, 16;
    @%p15 ld.shared.f32 %f26, [%r65];
    @%p15 max.f32 %f27, %f25, %f26;
    @%p15 st.shared.f32 [%r48], %f27;
    bar.sync 0;

    setp.lt.u32 %p16, %r2, 2;
    @%p16 ld.shared.f32 %f28, [%r48];
    @%p16 add.u32 %r66, %r48, 8;
    @%p16 ld.shared.f32 %f29, [%r66];
    @%p16 max.f32 %f30, %f28, %f29;
    @%p16 st.shared.f32 [%r48], %f30;
    bar.sync 0;

    setp.lt.u32 %p17, %r2, 1;
    @%p17 ld.shared.f32 %f31, [%r48];
    @%p17 add.u32 %r67, %r48, 4;
    @%p17 ld.shared.f32 %f32, [%r67];
    @%p17 max.f32 %f33, %f31, %f32;
    @%p17 st.shared.f32 [%r48], %f33;
    bar.sync 0;

    ld.shared.f32 %f34, [%r13];     // maxVal = Rd[0]

    // ---------------- Compute exp(score - max) ----------------
    sub.f32 %f35, %f1, %f34;
    mul.f32 %f36, %f35, 0f3FB8AA3B;  // * log2(e)
    ex2.approx.f32 %f37, %f36;
    st.shared.f32 [%r47], %f37;      // Ex[tid] = expval
    bar.sync 0;

    ld.shared.f32 %f38, [%r47];
    st.shared.f32 [%r48], %f38;      // Rd[tid] = copy for sum reduction
    bar.sync 0;

    // ---------------- SUM REDUCTION ----------------
    setp.lt.u32 %p20, %r2, 128;
    @%p20 ld.shared.f32 %f40, [%r48];
    @%p20 add.u32 %r70, %r48, 512;
    @%p20 ld.shared.f32 %f41, [%r70];
    @%p20 add.f32 %f42, %f40, %f41;
    @%p20 st.shared.f32 [%r48], %f42;
    bar.sync 0;

    setp.lt.u32 %p21, %r2, 64;
    @%p21 ld.shared.f32 %f43, [%r48];
    @%p21 add.u32 %r71, %r48, 256;
    @%p21 ld.shared.f32 %f44, [%r71];
    @%p21 add.f32 %f45, %f43, %f44;
    @%p21 st.shared.f32 [%r48], %f45;
    bar.sync 0;

    setp.lt.u32 %p22, %r2, 32;
    @%p22 ld.shared.f32 %f46, [%r48];
    @%p22 add.u32 %r72, %r48, 128;
    @%p22 ld.shared.f32 %f47, [%r72];
    @%p22 add.f32 %f48, %f46, %f47;
    @%p22 st.shared.f32 [%r48], %f48;
    bar.sync 0;

    setp.lt.u32 %p23, %r2, 16;
    @%p23 ld.shared.f32 %f49, [%r48];
    @%p23 add.u32 %r73, %r48, 64;
    @%p23 ld.shared.f32 %f50, [%r73];
    @%p23 add.f32 %f51, %f49, %f50;
    @%p23 st.shared.f32 [%r48], %f51;
    bar.sync 0;

    setp.lt.u32 %p24, %r2, 8;
    @%p24 ld.shared.f32 %f52, [%r48];
    @%p24 add.u32 %r74, %r48, 32;
    @%p24 ld.shared.f32 %f53, [%r74];
    @%p24 add.f32 %f54, %f52, %f53;
    @%p24 st.shared.f32 [%r48], %f54;
    bar.sync 0;

    setp.lt.u32 %p25, %r2, 4;
    @%p25 ld.shared.f32 %f55, [%r48];
    @%p25 add.u32 %r75, %r48, 16;
    @%p25 ld.shared.f32 %f56, [%r75];
    @%p25 add.f32 %f57, %f55, %f56;
    @%p25 st.shared.f32 [%r48], %f57;
    bar.sync 0;

    setp.lt.u32 %p26, %r2, 2;
    @%p26 ld.shared.f32 %f58, [%r48];
    @%p26 add.u32 %r76, %r48, 8;
    @%p26 ld.shared.f32 %f59, [%r76];
    @%p26 add.f32 %f60, %f58, %f59;
    @%p26 st.shared.f32 [%r48], %f60;
    bar.sync 0;

    setp.lt.u32 %p27, %r2, 1;
    @%p27 ld.shared.f32 %f61, [%r48];
    @%p27 add.u32 %r77, %r48, 4;
    @%p27 ld.shared.f32 %f62, [%r77];
    @%p27 add.f32 %f63, %f61, %f62;
    @%p27 st.shared.f32 [%r48], %f63;
    bar.sync 0;

    ld.shared.f32 %f64, [%r13];     // denom = Rd[0]

    // weight = expval / denom, store into Sc[tid]
    ld.shared.f32 %f65, [%r47];
    div.rn.f32 %f66, %f65, %f64;
    st.shared.f32 [%r46], %f66;
    bar.sync 0;

    // ---------------- Output computation ----------------
    mov.u32 %r80, 0;
OUT_K_LOOP:
    setp.ge.u32 %p30, %r80, 4;
    @%p30 bra OUT_K_DONE;

    shl.b32 %r81, %r80, 8;
    add.u32 %r82, %r2, %r81;        // d = tid + k*256

    mov.f32 %f70, 0f00000000;
    mov.u32 %r83, 0;
OUT_J_LOOP:
    setp.ge.u32 %p31, %r83, 256;
    @%p31 bra OUT_J_DONE;

    shl.b32 %r84, %r83, 2;
    add.u32 %r85, %r11, %r84;       // Sc[j] addr
    ld.shared.f32 %f71, [%r85];

    add.u32 %r86, %r5, %r83;        // rowIndexV = bhS + j
    shl.b32 %r87, %r86, 11;         // byteOffV
    cvt.u64.u32 %rd30, %r87;
    add.s64 %rd31, %rd3, %rd30;     // V row base

    shl.b32 %r88, %r82, 1;          // d*2
    cvt.u64.u32 %rd32, %r88;
    add.s64 %rd33, %rd31, %rd32;    // V element addr

    ld.global.b16 %h10, [%rd33];
    cvt.f32.f16 %f72, %h10;

    fma.rn.f32 %f70, %f71, %f72, %f70;

    add.u32 %r83, %r83, 1;
    bra OUT_J_LOOP;
OUT_J_DONE:

    cvt.u64.u32 %rd34, %r6;
    add.s64 %rd35, %rd4, %rd34;     // Out row base
    shl.b32 %r89, %r82, 1;
    cvt.u64.u32 %rd36, %r89;
    add.s64 %rd37, %rd35, %rd36;

    cvt.rn.f16.f32 %h11, %f70;
    st.global.b16 [%rd37], %h11;

    add.u32 %r80, %r80, 1;
    bra OUT_K_LOOP;
OUT_K_DONE:

DONE_ALL:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sdpa_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.shape == K.shape == V.shape
        B, H, S, D = Q.shape
        assert B == 2 and H == 32 and S == 256 and D == 1024
        assert Q.dtype == torch.float16 and Q.is_cuda

        Q = Q.contiguous()
        K = K.contiguous()
        V = V.contiguous()
        out = torch.empty_like(Q)

        module = _get_ptx_module()

        total_blocks = B * H * S  # 16384
        module.launch(
            "sdpa_kernel",
            grid=(total_blocks, 1, 1),
            block=(256, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )

        return out

